async function seedDatabase() {
  try {
    await sequelize.authenticate();
    logger.info('✅ Connected to Cloud Database. Starting global seed...');

    // Enable geographical math
    await sequelize.query('CREATE EXTENSION IF NOT EXISTS postgis;');

    // 1. CREATE THE TABLE AUTOMATICALLY
    await sequelize.query(`
      CREATE TABLE IF NOT EXISTS signals (
        id VARCHAR(255) PRIMARY KEY,
        intersection_name VARCHAR(255),
        latitude DOUBLE PRECISION,
        longitude DOUBLE PRECISION,
        location GEOMETRY(Point, 4326),
        current_phase VARCHAR(50),
        seconds_remaining INTEGER,
        green_duration INTEGER,
        yellow_duration INTEGER,
        red_duration INTEGER,
        cycle_time INTEGER,
        created_at TIMESTAMP WITH TIME ZONE,
        updated_at TIMESTAMP WITH TIME ZONE
      );
    `);
    logger.info('✅ Signals table created & verified');

    // 2. INJECT THE SIGNALS safely
    for (let i = 0; i < karnatakaSignals.length; i++) {
      const sig = karnatakaSignals[i];
      
      // We automatically set green/yellow/red durations since your array only uses 'timer'
      const green = 45;
      const yellow = 5;
      const red = 60;
      const phase = sig.phase || 'red';
      const timer = sig.timer || 45;

      // Ensure names with apostrophes don't break the SQL query
      const safeName = sig.name.replace(/'/g, "''");

      await sequelize.query(`
        INSERT INTO signals (
          id, intersection_name, latitude, longitude, location, 
          current_phase, seconds_remaining, 
          green_duration, yellow_duration, red_duration, cycle_time,
          created_at, updated_at
        )
        VALUES (
          '${sig.id}', '${safeName}', ${sig.lat}, ${sig.lon},
          ST_SetSRID(ST_MakePoint(${sig.lon}, ${sig.lat}), 4326),
          '${phase}', ${timer},
          ${green}, ${yellow}, ${red}, ${green + yellow + red},
          NOW(), NOW()
        )
        ON CONFLICT (id) DO UPDATE SET 
          latitude = EXCLUDED.latitude, 
          longitude = EXCLUDED.longitude, 
          location = EXCLUDED.location;
      `);

      process.stdout.write(`\rSeeded ${i + 1}/${karnatakaSignals.length} signals...`);
    }

    logger.info('\n🎉 All 525 Karnataka signals successfully uploaded!');
    process.exit(0);
  } catch (error) {
    logger.error('\n❌ Seeding failed: ' + error.message);
    process.exit(1);
  }
}

seedDatabase();